begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('db410000-0000-4000-8000-000000000001','lab-provenance-staff@example.test','{}'),
('db410000-0000-4000-8000-000000000002','lab-provenance-dvm@example.test','{}'),
('db410000-0000-4000-8000-000000000003','lab-provenance-inactive@example.test','{}');
update public.profiles set is_active = true where id in ('db410000-0000-4000-8000-000000000001','db410000-0000-4000-8000-000000000002','db410000-0000-4000-8000-000000000003');
insert into public.user_roles (user_id, role) values ('db410000-0000-4000-8000-000000000001','STAFF'),('db410000-0000-4000-8000-000000000002','STAFF'),('db410000-0000-4000-8000-000000000003','STAFF');

insert into public.user_roles(user_id,role) values('db410000-0000-4000-8000-000000000001','ADMIN'),('db410000-0000-4000-8000-000000000002','DVM');
update public.profiles set is_active=false where id='db410000-0000-4000-8000-000000000003';
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated,service_role;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"db410000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Synthetic','Lab',null,null,'EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'One','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Two','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select k,gen_random_uuid() from unnest(array['order','source','foreign-source','doc','corrected-doc','other-doc','receipt','corrected-receipt','other-receipt','mapping','report','corrected-report','ack']) k;
select public.save_patient_lab_order((select id from fx where k='order'),(select id from fx where k='pet'),null,'{"test_name":"Synthetic lab","status":"planned","due_date":"2026-10-01","notes":"Local clinical notes remain unchanged"}','');
insert into data select 'order-before',to_jsonb(o) from public.patient_lab_orders o where id=(select id from fx where k='order');
select public.review_lab_source_account((select id from fx where k='source'),'Synthetic source','Manually reviewed account','Training environment','Synthetic test only; not Antech commissioning');
select public.review_lab_source_account((select id from fx where k='foreign-source'),'Synthetic source','Other account','Training environment','Different manual source');
select lives_ok($$select public.review_lab_source_account((select id from fx where k='source'),'Synthetic source','Manually reviewed account','Training environment','Synthetic test only; not Antech commissioning')$$,'Source setup exact actor-scoped replay');
reset role;
-- Metadata-only synthetic document fixture; the service digest contract is tested separately from storage byte transport.
create function pg_temp.ready_doc(p_id uuid,p_pet uuid) returns void language plpgsql security definer set search_path=public as $$declare d public.patient_documents;begin
 d:=public.prepare_patient_document(p_id,p_pet,null,'synthetic.pdf','application/pdf',12,'lab_result','Synthetic manual fixture',null,'internal');
 insert into storage.objects(bucket_id,name,metadata) values('patient-documents',d.file_path,'{"size":12,"mimetype":"application/pdf"}');
 perform public.finalize_patient_document(p_id);
end $$;
select pg_temp.ready_doc((select id from fx where k='doc'),(select id from fx where k='pet'));
select pg_temp.ready_doc((select id from fx where k='corrected-doc'),(select id from fx where k='pet'));
select pg_temp.ready_doc((select id from fx where k='other-doc'),(select id from fx where k='other'));
set local role authenticated;
insert into data values('received',jsonb_build_object('at',clock_timestamp()));
insert into data select 'receipt',to_jsonb(public.stage_lab_report_receipt((select id from fx where k='receipt'),(select id from fx where k='source'),(select id from fx where k='doc'),2,'manual-patient','manual-order','report-original',(select (v->>'at')::timestamptz from data where k='received')));
select lives_ok($$select public.stage_lab_report_receipt((select id from fx where k='receipt'),(select id from fx where k='source'),(select id from fx where k='doc'),2,'manual-patient','manual-order','report-original',(select (v->>'at')::timestamptz from data where k='received'))$$,'Staff stages source refs without any hash input');
select is(jsonb_array_length(public.read_lab_result_history((select id from fx where k='pet'))->'staged_receipts'),1,'Unlinked receipt discoverable without native order promotion');
select public.review_lab_order_source((select id from fx where k='mapping'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='source'),'manual-patient','manual-order',null,'Reviewed source identity',true);
select throws_ok($$select public.link_lab_report_version((select id from fx where k='report'),(select id from fx where k='receipt'),(select v->>'receipt_hash' from data where k='receipt'),repeat('a',64),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),null,'original','Reviewed original report',true)$$,'42501',null,'Pending receipt cannot be promoted without service byte verification');
select throws_ok($$select public.capture_lab_report_bytes((select id from fx where k='receipt'),auth.uid(),(select v->>'receipt_hash' from data where k='receipt'),2,repeat('a',64),12,'application/pdf')$$,'42501',null,'Staff cannot assert a service byte digest');
set local role service_role;
select throws_ok($$select public.lab_report_capture_context((select id from fx where k='receipt'),'db410000-0000-4000-8000-000000000002')$$,'42501',null,'Capture context bound to staging actor');
select throws_ok($$select public.capture_lab_report_bytes((select id from fx where k='receipt'),'db410000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='receipt'),2,repeat('a',64),13,'application/pdf')$$,'23514',null,'Wrong original byte size denied');
insert into data select 'capture',to_jsonb(public.capture_lab_report_bytes((select id from fx where k='receipt'),'db410000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='receipt'),2,repeat('a',64),12,'application/pdf'));
select throws_ok($$select public.capture_lab_report_bytes((select id from fx where k='receipt'),'db410000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='receipt'),2,repeat('b',64),12,'application/pdf')$$,'23505',null,'Original byte digest cannot be replaced');
set local role authenticated;
select throws_ok($$select public.link_lab_report_version((select id from fx where k='report'),(select id from fx where k='receipt'),(select v->>'receipt_hash' from data where k='receipt'),(select v->>'capture_hash' from data where k='capture'),(select id from fx where k='order'),(select id from fx where k='other'),1,(select id from fx where k='mapping'),null,'original','Reviewed original report',true)$$,'42501',null,'Cross-patient promotion denied');
insert into data select 'foreign-receipt',to_jsonb(public.stage_lab_report_receipt(gen_random_uuid(),(select id from fx where k='foreign-source'),(select id from fx where k='doc'),2,'manual-patient','manual-order','other-account-report',(select (v->>'at')::timestamptz from data where k='received')));
select throws_ok($$select public.link_lab_report_version(gen_random_uuid(),(select (v->>'id')::uuid from data where k='foreign-receipt'),(select v->>'receipt_hash' from data where k='foreign-receipt'),repeat('a',64),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),null,'original','Reviewed source',true)$$,'42501',null,'Same-patient document cannot cross reviewed source account');
insert into data select 'other-patient-receipt',to_jsonb(public.stage_lab_report_receipt((select id from fx where k='other-receipt'),(select id from fx where k='source'),(select id from fx where k='other-doc'),2,'manual-patient','manual-order','other-patient-report',(select (v->>'at')::timestamptz from data where k='received')));
select throws_ok($$select public.link_lab_report_version(gen_random_uuid(),(select id from fx where k='other-receipt'),(select v->>'receipt_hash' from data where k='other-patient-receipt'),repeat('a',64),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),null,'original','Reviewed source',true)$$,'42501',null,'Different patient private document cannot be promoted to order');
select throws_ok($$select public.link_lab_report_version(gen_random_uuid(),(select id from fx where k='receipt'),(select v->>'receipt_hash' from data where k='receipt'),(select v->>'capture_hash' from data where k='capture'),(select id from fx where k='order'),(select id from fx where k='pet'),0,(select id from fx where k='mapping'),null,'original','Reviewed source',true)$$,'40001',null,'Order version changes invalidate reviewed promotion');
select lives_ok($$select public.link_lab_report_version((select id from fx where k='report'),(select id from fx where k='receipt'),(select v->>'receipt_hash' from data where k='receipt'),(select v->>'capture_hash' from data where k='capture'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),null,'original','Reviewed original report',true)$$,'Reviewed captured original linked');
select lives_ok($$select public.link_lab_report_version((select id from fx where k='report'),(select id from fx where k='receipt'),(select v->>'receipt_hash' from data where k='receipt'),(select v->>'capture_hash' from data where k='capture'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),null,'original','Reviewed original report',true)$$,'Report UUID replay creates no new version');
select is(jsonb_array_length(public.read_lab_result_history((select id from fx where k='pet'))#>'{reports,0,acknowledgments}'),0,'Import never acknowledges clinical review');
select throws_ok($$select public.acknowledge_lab_report((select id from fx where k='ack'),(select id from fx where k='report'),(select id from fx where k='pet'),(select v->>'capture_hash' from data where k='capture'),2,true)$$,'42501',null,'Administrator alone cannot acknowledge as veterinarian');
select set_config('request.jwt.claims','{"sub":"db410000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.acknowledge_lab_report((select id from fx where k='ack'),(select id from fx where k='report'),(select id from fx where k='pet'),(select v->>'capture_hash' from data where k='capture'),2,true)$$,'Active DVM independently acknowledges exact report');
select lives_ok($$select public.acknowledge_lab_report((select id from fx where k='ack'),(select id from fx where k='report'),(select id from fx where k='pet'),(select v->>'capture_hash' from data where k='capture'),2,true)$$,'Acknowledgment replay idempotent');
select set_config('request.jwt.claims','{"sub":"db410000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into data select 'corrected-receipt',to_jsonb(public.stage_lab_report_receipt((select id from fx where k='corrected-receipt'),(select id from fx where k='source'),(select id from fx where k='corrected-doc'),2,'manual-patient','manual-order','report-corrected',(select (v->>'at')::timestamptz from data where k='received')));
set local role service_role;
insert into data select 'corrected-capture',to_jsonb(public.capture_lab_report_bytes((select id from fx where k='corrected-receipt'),'db410000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='corrected-receipt'),2,repeat('b',64),12,'application/pdf'));
set local role authenticated;
select throws_ok($$select public.link_lab_report_version((select id from fx where k='corrected-report'),(select id from fx where k='corrected-receipt'),(select v->>'receipt_hash' from data where k='corrected-receipt'),(select v->>'capture_hash' from data where k='corrected-capture'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),null,'corrected','Reviewed correction',true)$$,'40001',null,'Concurrent changed report head requires fresh review');
select public.link_lab_report_version((select id from fx where k='corrected-report'),(select id from fx where k='corrected-receipt'),(select v->>'receipt_hash' from data where k='corrected-receipt'),(select v->>'capture_hash' from data where k='corrected-capture'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='mapping'),(select id from fx where k='report'),'corrected','Reviewed correction',true);
select is(jsonb_array_length(public.read_lab_result_history((select id from fx where k='pet'))->'reports'),2,'Original and corrected reports retained');
select is(jsonb_array_length(public.read_lab_result_history((select id from fx where k='pet'))#>'{reports,1,acknowledgments}'),0,'Earlier clinician acknowledgment does not cover correction');
select is(public.read_lab_result_history((select id from fx where k='pet'))#>>'{reports,0,capture,content_sha256}',repeat('a',64),'Original file digest preserved alongside correction');
select is((select to_jsonb(o) from public.patient_lab_orders o where id=(select id from fx where k='order')),(select v from data where k='order-before'),'Notes, due plans, order status and legacy result pointer unchanged');
reset role;
select throws_ok($$delete from public.lab_report_receipts$$,'23514',null,'Source receipt history append-only');
select throws_ok($$update public.lab_report_versions set review_reason='Changed'$$,'23514',null,'Report corrections append rather than overwrite');
select throws_ok($$update public.lab_report_byte_captures set content_sha256=repeat('f',64)$$,'23514',null,'Original byte capture immutable');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"db410000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.read_lab_result_history((select id from fx where k='pet'))$$,'42501',null,'Inactive staff cannot read result provenance');
set local role anon;
select throws_ok($$select * from public.lab_report_versions$$,'42501',null,'Anonymous private reports denied');
select * from finish();rollback;
